<?php
namespace NexoCursos;
defined('ABSPATH') || exit;
final class PortalSales {
    public static function statuses(): array {return ['pending'=>'Pagamento pendente','on-hold'=>'Em espera','processing'=>'Pago / em processamento','completed'=>'Concluído','cancelled'=>'Cancelado','refunded'=>'Reembolsado','failed'=>'Falhou'];}
    public static function money($amount,string $currency=''): string {return wp_kses_post(wc_price((float)$amount,['currency'=>$currency?:get_woocommerce_currency()]));}
    public static function product_allowed($p): bool {
        if(!Portal::allowed()||!$p){return false;}if(PortalOrders::storewide()){return true;}$ids=Core::product_courses($p->is_type('variation')?$p->get_parent_id():$p->get_id(),$p->is_type('variation')?$p->get_id():0);if(!$ids){return false;}foreach($ids as $id){if(!Core::can_manage($id)){return false;}}return true;
    }
    public static function products(): array {
        if(PortalOrders::storewide()){return wc_get_products(['limit'=>-1,'status'=>['publish','draft','private'],'orderby'=>'title','order'=>'ASC']);}
        $out=[];foreach(Portal::courses() as $c){$id=(int)get_post_meta($c->ID,'_nexo_product_id',true);$p=$id?wc_get_product($id):false;if($p&&self::product_allowed($p)){$out[$id]=$p;}}return array_values($out);
    }
    public static function mutate(string $action,array $d) {
        if(!class_exists('WooCommerce')){return new \WP_Error('woo','As vendas estão indisponíveis no momento.');}if($action==='product_save'){return self::product_save($d);}if($action==='orders_sync'){PortalOrders::backfill();return ['message'=>get_option('nexo_order_index_done')?'Histórico de pedidos pronto.':'Mais uma parte do histórico foi organizada. O restante continua em segundo plano.','view'=>'orders'];}return PortalOrders::mutate($action,$d);
    }
    private static function product_save(array $d) {
        $id=Portal::id($d,'product_id');$p=$id?wc_get_product($id):null;if(($id&&(!$p||!self::product_allowed($p)))||(!$id&&!PortalOrders::storewide())){return new \WP_Error('forbidden','Você não pode editar este produto.');}
        $name=Portal::text($d,'name');$status=Portal::text($d,'status');$raw=Portal::text($d,'price');$price=wc_format_decimal($raw);$sale_raw=Portal::text($d,'sale_price');$sale=$sale_raw!==''?wc_format_decimal($sale_raw):'';
        if(!$name||!in_array($status,['publish','draft','private'],true)||!is_numeric($price)||(float)$price<0||($sale!==''&&(!is_numeric($sale)||(float)$sale<0||(float)$sale>=(float)$price))){return new \WP_Error('product','Confira nome, situação e preços. O preço promocional deve ser menor que o preço normal.');}
        $sku=Portal::text($d,'sku');if($sku&&!wc_product_has_unique_sku($id,$sku)){return new \WP_Error('sku','Este código de produto já está em uso. Escolha outro.');}
        $owned=$p?absint($p->get_meta('_nexo_managed_course_id',true)):0;if($owned&&((is_wp_error(Portal::course($owned))&&!current_user_can('manage_woocommerce'))||(float)$price<=0)){return new \WP_Error('course','O produto do curso precisa de um preço maior que zero. Para torná-lo gratuito, altere a inscrição no curso.');}
        if($p&&!$p->is_type(['simple','variation'])){return new \WP_Error('type','Selecione uma variação para alterar seus valores.');}
        $image=Portal::upload('product_image',$owned);if(is_wp_error($image)){return $image;}
        try{
            if(!$p){$p=new \WC_Product_Simple();}$description=wp_kses_post(wp_unslash(is_string($d['description']??null)?$d['description']:''));
            if($owned){$r=wp_update_post(['ID'=>$owned,'post_title'=>mb_substr($name,0,180),'post_content'=>$description,'post_status'=>$status,'meta_input'=>['_nexo_price'=>(string)$price,'_nexo_sale_price'=>$sale]],true);if(is_wp_error($r)){return $r;}if($image){set_post_thumbnail($owned,$image);}elseif(!empty($d['remove_product_image'])){delete_post_thumbnail($owned);}Commerce::sync_product($owned);$p=wc_get_product($id);}
            else{$p->set_name(mb_substr($name,0,180));$p->set_description($description);$p->set_regular_price($price);$p->set_sale_price($sale);$p->set_status($status);$p->set_virtual(!empty($d['virtual']));if($image){$p->set_image_id($image);}elseif(!empty($d['remove_product_image'])){$p->set_image_id(0);}}
            $p->set_manage_stock(!empty($d['manage_stock']));if(!empty($d['manage_stock'])){$p->set_stock_quantity(Portal::id($d,'stock_quantity'));$p->set_backorders('no');$p->set_stock_status(Portal::id($d,'stock_quantity')>0?'instock':'outofstock');}else{$p->set_stock_status(Portal::text($d,'stock_status')==='outofstock'?'outofstock':'instock');}
            $p->set_sold_individually($owned?true:!empty($d['sold_individually']));$p->set_sku(Portal::text($d,'sku'));$saved=$p->save();return ['message'=>'Produto salvo. Preço e estoque foram atualizados.','view'=>'products','args'=>['product_id'=>$saved]];
        }catch(\Throwable $e){return new \WP_Error('product','Não foi possível salvar. Confira se o código do produto já está em uso.');}
    }
    public static function render(string $view): void {
        if(!class_exists('WooCommerce')){echo '<section class="np-card"><h2>Vendas indisponíveis</h2><p>A gestão dos cursos continua disponível. O administrador pode ativar as vendas da plataforma.</p></section>';return;}
        if($view==='products'){self::product_screen();return;}
        if(!get_option('nexo_order_index_done')){PortalOrders::backfill();}
        if($view==='orders'&&Portal::id($_GET,'order_id')){self::detail(Portal::id($_GET,'order_id'));return;}
        if($view==='orders'&&Portal::text($_GET,'editor')==='new'){self::new_order();return;}
        $f=PortalOrders::filters($_GET);if(is_wp_error($f)){echo '<p class="np-error">'.esc_html($f->get_error_message()).'</p><a class="np-button np-secondary" href="'.esc_url(Portal::url($view)).'">Limpar filtros</a>';return;}
        if(!get_option('nexo_order_index_done')){echo '<div class="np-notice" role="status">O histórico antigo está sendo organizado. Novos pedidos já são acompanhados automaticamente.'.Portal::form('orders_sync','orders').Portal::button('Continuar organização do histórico','np-secondary').'</form></div>';}
        self::filters($view,$f);
        if($view==='sales'){self::report($f);return;}
        echo '<div class="np-section-actions"><p>Pedidos e pagamentos dos produtos sob sua gestão.</p><a class="np-button" href="'.esc_url(Portal::url('orders',['editor'=>'new'])).'">＋ Criar pedido</a></div>';
        $page=max(1,Portal::id($_GET,'orders_page'));$list=PortalOrders::listing($f,$page);echo '<div class="np-order-list">';
        foreach($list['orders'] as $o){$names=[];foreach(PortalOrders::visible_items($o,$f['course']) as $item){$names[]=$item->get_name();}echo '<article class="np-card np-order"><div class="np-row"><h2>Pedido #'.esc_html($o->get_order_number()).'</h2><span class="np-badge">'.esc_html(self::statuses()[$o->get_status()]??wc_get_order_status_name($o->get_status())).'</span></div><p>'.esc_html($o->get_date_created()?wp_date('d/m/Y H:i',$o->get_date_created()->getTimestamp()):'').'</p><p class="np-break">'.esc_html($o->get_formatted_billing_full_name()?:'Aluno').'</p><p>'.esc_html(implode(' · ',$names)).'</p><strong class="np-price">'.self::money(PortalOrders::amount($o,$f['course']),$o->get_currency()).'</strong><a class="np-button np-secondary" href="'.esc_url(Portal::url('orders',['order_id'=>$o->get_id()])).'">Abrir pedido</a></article>';}
        echo '</div>';if(!$list['orders']){echo '<p class="np-empty">Nenhum pedido encontrado neste período.</p>';}self::pagination('orders',$f,$page,$list['pages']);
    }
    private static function filter_args(array $f): array {return ['from'=>$f['from'],'to'=>$f['to'],'course_id'=>$f['course'],'order_status'=>$f['status'],'order_number'=>$f['order'],'currency'=>$f['currency']];}
    private static function filters(string $view,array $f): void {
        $courses=[0=>PortalOrders::storewide()?'Todos os produtos':'Todos os meus cursos'];foreach(Portal::courses() as $c){$courses[$c->ID]=$c->post_title;}
        echo '<form method="get" action="'.esc_url(nexo_page_url('dashboard')).'" class="np-filters">'.Portal::get_fields($view).Portal::input('De','from',$f['from'],'date').Portal::input('Até','to',$f['to'],'date').Portal::select('Curso','course_id',$courses,$f['course']).Portal::select('Situação','order_status',[''=>'Todas']+self::statuses(),$f['status']);
        if($view==='orders'){echo Portal::input('Número do pedido','order_number',$f['order']?:'','number','min="1"');}else{$currencies=[$f['currency']=>$f['currency'],get_woocommerce_currency()=>get_woocommerce_currency()];echo Portal::select('Moeda dos totais','currency',$currencies,$f['currency']);}echo Portal::button('Aplicar filtros','np-secondary').'</form>';
    }
    private static function pagination(string $view,array $f,int $page,int $pages): void {if($pages<2){return;}echo '<nav class="np-pagination" aria-label="Páginas de pedidos">';foreach(range(max(1,$page-2),min($pages,$page+2)) as $i){echo '<a '.($i===$page?'aria-current="page"':'').' href="'.esc_url(Portal::url($view,array_merge(self::filter_args($f),['orders_page'=>$i]))).'">'.$i.'</a>';}echo '</nav>';}
    private static function report(array $f): void {
        $total=0.0;$paid=0;$pending=0;$series=[];$page=1;
        do{$batch=PortalOrders::listing($f,$page,200);foreach($batch['orders'] as $o){if($o->get_currency()!==$f['currency']){continue;}$value=PortalOrders::amount($o,$f['course']);if($o->has_status(['processing','completed'])){$total+=$value;$paid++;$date=wp_date('Y-m-d',$o->get_date_created()->getTimestamp());$series[$date]=($series[$date]??0)+$value;}elseif($o->has_status(['pending','on-hold'])){$pending++;}}$page++;}while($page<=$batch['pages']);
        echo '<p class="np-lead">Valores pagos, já descontados os reembolsos, na moeda '.esc_html($f['currency']).'. O período usa a data de criação dos pedidos.</p><div class="np-kpis"><article class="np-kpi"><span>Vendas pagas líquidas</span><strong>'.self::money($total,$f['currency']).'</strong></article><article class="np-kpi"><span>Pedidos pagos</span><strong>'.$paid.'</strong></article><article class="np-kpi"><span>Pagamento pendente / em espera</span><strong>'.$pending.'</strong></article><article class="np-kpi"><span>Valor médio pago</span><strong>'.self::money($paid?$total/$paid:0,$f['currency']).'</strong></article></div>';
        ksort($series);$series=array_slice($series,-12,true);echo '<section class="np-card"><h2>Vendas por dia</h2><p>Até 12 dias com vendas no período selecionado.</p>';if(!$series){echo '<p class="np-empty">As vendas pagas aparecerão aqui.</p>';}else{$max=max(1,max($series));echo '<div class="np-chart-scroll"><div class="np-sales-bars" role="img" aria-label="Vendas pagas por dia. Valores disponíveis na tabela abaixo.">';foreach($series as $date=>$value){echo '<div><strong>'.self::money($value,$f['currency']).'</strong><span class="np-sales-track"><i style="height:'.(int)round(100*$value/$max).'%"></i></span><small>'.esc_html(Calendar::date($date)->format('d/m')).'</small></div>';}echo '</div></div><details><summary>Ver valores por dia</summary><table class="np-table"><thead><tr><th>Data</th><th>Valor pago líquido</th></tr></thead><tbody>';foreach($series as $date=>$value){echo '<tr><td>'.esc_html(Calendar::date($date)->format('d/m/Y')).'</td><td>'.self::money($value,$f['currency']).'</td></tr>';}echo '</tbody></table></details>';}echo '</section>';
        echo '<section class="np-card"><h2>Relatório</h2><p>Baixe os pedidos e itens visíveis para sua conta no período selecionado.</p>'.Portal::form('sales_export','sales',self::filter_args($f)).Portal::button('Baixar relatório CSV','np-secondary').'</form></section>';
    }
    private static function detail(int $id): void {
        $o=PortalOrders::access($id);if(is_wp_error($o)){echo '<p class="np-error">'.esc_html($o->get_error_message()).'</p>';return;}$full=PortalOrders::full($o);$items=PortalOrders::visible_items($o);
        echo '<a class="np-back" href="'.esc_url(Portal::url('orders')).'">← Todos os pedidos</a><section class="np-card"><div class="np-row"><h2>Pedido #'.esc_html($o->get_order_number()).'</h2><span class="np-badge">'.esc_html(self::statuses()[$o->get_status()]??wc_get_order_status_name($o->get_status())).'</span></div><p>'.esc_html($o->get_date_created()?wp_date('d/m/Y H:i',$o->get_date_created()->getTimestamp()):'').'</p><p>'.esc_html($o->get_formatted_billing_full_name()?:'Aluno').'<br><span class="np-break">'.esc_html($o->get_billing_email()).'</span></p><div class="np-table-wrap"><table class="np-table"><thead><tr><th>Produto</th><th>Quantidade</th><th>Valor dos itens</th></tr></thead><tbody>';
        foreach($items as $item){echo '<tr><td>'.esc_html($item->get_name()).'</td><td>'.esc_html($item->get_quantity()).'</td><td>'.self::money((float)$item->get_total()+(float)$item->get_total_tax(),$o->get_currency()).'</td></tr>';}
        echo '</tbody></table></div><p class="np-order-total">Valor líquido sob sua gestão: <strong>'.self::money(PortalOrders::amount($o),$o->get_currency()).'</strong></p>';
        if($full){echo '<p>Meio de pagamento: '.esc_html($o->get_payment_method_title()?:'A definir').'</p>';if($o->needs_payment()){echo '<a class="np-button" href="'.esc_url($o->get_checkout_payment_url()).'" target="_blank" rel="noopener">Abrir link de pagamento ↗</a>';}if(Portal::finance()){echo '<details class="np-settings-section"><summary>Dados de cobrança e entrega</summary><div class="np-two-columns"><div>'.wp_kses_post($o->get_formatted_billing_address()?:'Sem endereço informado.').'</div><div>'.wp_kses_post($o->get_formatted_shipping_address()?:'Sem entrega física.').'</div></div></details>';}}
        else{echo '<p class="np-help">Este pedido inclui itens fora dos seus cursos. Aqui aparecem os itens sob sua gestão.</p>';}echo '</section>';
        if(!$full){return;}
        if(!$o->has_status('refunded')&&(Portal::finance()||$o->has_status('processing'))){$statuses=Portal::finance()?array_diff_key(self::statuses(),['refunded'=>true]):['completed'=>'Concluído'];echo '<section class="np-card"><h2>Atualizar situação</h2>'.Portal::form('order_status','orders',['order_id'=>$id]).Portal::select('Situação','status',$statuses,$o->get_status());if(Portal::finance()){echo '<label class="np-check"><input type="checkbox" name="confirm_paid" value="1"> Confirmo o recebimento do pagamento, se estiver liberando o acesso manualmente</label><p class="np-help">Alterar para pago / em processamento ou concluído libera a matrícula. Essa alteração não faz uma cobrança no cartão.</p>';}echo Portal::button('Salvar situação').'</form></section>';}
        echo '<section class="np-card"><h2>Observações da equipe</h2><ul class="np-order-notes">';foreach(wc_get_order_notes(['order_id'=>$id,'limit'=>20,'orderby'=>'date_created','order'=>'DESC']) as $note){echo '<li><small>'.esc_html(wp_date('d/m/Y H:i',$note->date_created->getTimestamp())).'</small><p>'.esc_html(wp_strip_all_tags($note->content)).'</p></li>';}echo '</ul>'.Portal::form('order_note','orders',['order_id'=>$id]).Portal::textarea('Nova observação interna','note','',3,'required maxlength="2000"').Portal::button('Adicionar observação','np-secondary').'</form></section>';
        if(Portal::finance()){
            echo '<details class="np-card np-settings-section"><summary>Vincular conta do aluno</summary><p>Vincule uma conta existente quando o pedido estiver sem aluno ou precisar ser corrigido. As matrículas por este pedido serão transferidas para essa conta.</p>'.Portal::form('order_customer','orders',['order_id'=>$id]).Portal::input('E-mail da conta','email','','email','required').'<label class="np-check"><input type="checkbox" name="confirm_customer" value="1" required> Confirmo a conta que receberá o acesso deste pedido</label>'.Portal::button('Vincular conta','np-secondary').'</form></details>';
            if($o->has_status(['processing','completed'])&&(float)$o->get_remaining_refund_amount()>0){echo '<details class="np-card np-settings-section"><summary>Reembolsar saldo restante</summary><p>Saldo: <strong>'.self::money($o->get_remaining_refund_amount(),$o->get_currency()).'</strong>. O reembolso integral encerra o acesso concedido por este pedido, preservando outras compras ou matrículas válidas.</p>'.Portal::form('order_refund','orders',['order_id'=>$id]).Portal::select('Como devolver o valor','refund_method',[''=>'Selecione','gateway'=>'Devolver pelo meio de pagamento','manual'=>'O valor já foi devolvido por outro meio — registrar manualmente'],'','required').Portal::textarea('Motivo','reason','',3,'required maxlength="1000"').'<p class="np-help">O registro manual não transfere dinheiro. A devolução pelo meio de pagamento depende do suporte do serviço usado na compra.</p><label class="np-check"><input type="checkbox" name="confirm_refund" value="1" required> Confirmo o reembolso de todo o saldo restante</label>'.Portal::button('Confirmar reembolso','np-danger').'</form></details>';}
        }
    }
    private static function new_order(): void {
        $options=[];foreach(self::products() as $p){if($p->get_status()==='publish'&&$p->is_purchasable()&&$p->is_in_stock()&&!$p->is_type(['variable','grouped'])){$options[$p->get_id()]=$p->get_name().' — '.html_entity_decode(wp_strip_all_tags(self::money($p->get_price())),ENT_QUOTES,'UTF-8');}}
        echo '<a class="np-back" href="'.esc_url(Portal::url('orders')).'">← Pedidos</a><section class="np-card"><h2>Novo pedido</h2><p>O pedido será criado com pagamento pendente para uma conta já cadastrada.</p>';if(!$options){echo '<p class="np-empty">Publique um produto com preço e estoque disponíveis antes de criar o pedido.</p></section>';return;}
        echo Portal::form('order_create','orders',['request_key'=>wp_generate_uuid4()]).Portal::input('E-mail da conta do aluno','email','','email','required').Portal::select('Produto','product_id',$options,array_key_first($options)).Portal::input('Cupom (opcional)','coupon').'<label class="np-check"><input type="checkbox" name="send_invoice" value="1"> Enviar o link de pagamento por e-mail</label>'.Portal::button('Criar pedido pendente').'</form></section>';
    }
    private static function product_screen(): void {
        $id=Portal::id($_GET,'product_id');$new=Portal::text($_GET,'editor')==='new';$p=$id?wc_get_product($id):null;if(($id&&(!$p||!self::product_allowed($p)))||($new&&!PortalOrders::storewide())){echo '<p class="np-error">Produto indisponível para sua conta.</p>';return;}
        if($id||$new){self::product_editor($p);return;}
        echo '<div class="np-section-actions"><p>Produtos, preços e estoque das inscrições.</p>'.(PortalOrders::storewide()?'<a class="np-button" href="'.esc_url(Portal::url('products',['editor'=>'new'])).'">＋ Criar produto</a>':(Portal::all_courses()?'<a class="np-button" href="'.esc_url(Portal::url('courses',['editor'=>'new'])).'">Criar curso e produto</a>':'')).'</div><div class="np-products-list">';
        $all=self::products();$page=max(1,Portal::id($_GET,'products_page'));$pages=max(1,(int)ceil(count($all)/24));foreach(array_slice($all,($page-1)*24,24) as $p){echo '<article class="np-card"><span class="np-badge">'.esc_html($p->get_status()==='publish'?'Publicado':'Rascunho / restrito').'</span><h2>'.esc_html($p->get_name()).'</h2><p class="np-price">'.wp_kses_post($p->get_price_html()).'</p><p>Estoque: '.esc_html($p->managing_stock()?(string)$p->get_stock_quantity():($p->is_in_stock()?'Disponível':'Indisponível')).'</p><a class="np-button np-secondary" href="'.esc_url(Portal::url('products',['product_id'=>$p->get_id()])).'">Editar produto</a></article>';}
        echo '</div>';if(!$all){echo '<p class="np-empty">Cursos pagos criam o produto ao serem salvos.</p>';}if($pages>1){echo '<nav class="np-pagination">';for($i=max(1,$page-2);$i<=min($pages,$page+2);$i++){echo '<a href="'.esc_url(Portal::url('products',['products_page'=>$i])).'">'.$i.'</a>';}echo '</nav>';}
    }
    private static function product_editor($p): void {
        echo '<a class="np-back" href="'.esc_url(Portal::url('products')).'">← Produtos</a>';
        if($p&&$p->is_type('variable')){echo '<section class="np-card"><h2>'.esc_html($p->get_name()).'</h2><p>Selecione uma variação para editar preço e estoque.</p><div class="np-stack">';foreach($p->get_children() as $id){$v=wc_get_product($id);if($v&&self::product_allowed($v)){echo '<a class="np-button np-secondary" href="'.esc_url(Portal::url('products',['product_id'=>$id])).'">'.esc_html($v->get_name()).'</a>';}}echo '</div></section>';return;}
        if($p&&!$p->is_type(['simple','variation'])){echo '<p class="np-empty">Este produto reúne outros produtos. Edite os itens individualmente.</p>';return;}
        $owned=$p?absint($p->get_meta('_nexo_managed_course_id',true)):0;echo '<section class="np-card"><h2>'.($p?'Editar produto':'Novo produto').'</h2>'.($owned?'<p>Este produto acompanha o curso. Título, descrição, preço e capa são compartilhados com ele.</p>':'').Portal::form('product_save','products',['product_id'=>$p?$p->get_id():0]).'<div class="np-form-grid">'.Portal::input('Nome','name',$p?$p->get_name():'','text','required maxlength="180"').Portal::select('Situação','status',['draft'=>'Rascunho','publish'=>'Publicado','private'=>'Restrito'],$p?$p->get_status():'draft').Portal::input('Preço normal','price',$p?$p->get_regular_price():'','number','min="0" step="0.01" required').Portal::input('Preço promocional (opcional)','sale_price',$p?$p->get_sale_price():'','number','min="0" step="0.01"').Portal::input('Código do produto (SKU)','sku',$p?$p->get_sku():'').Portal::input('Quantidade em estoque','stock_quantity',$p?$p->get_stock_quantity():'','number','min="0"').Portal::select('Disponibilidade sem controle de quantidade','stock_status',['instock'=>'Disponível','outofstock'=>'Indisponível'],$p?$p->get_stock_status():'instock').'</div><div class="np-check-grid"><label class="np-check"><input type="checkbox" name="manage_stock" value="1" '.checked($p?$p->get_manage_stock():false,true,false).'> Controlar estoque por quantidade</label>';
        if(!$owned){echo '<label class="np-check"><input type="checkbox" name="virtual" value="1" '.checked($p?$p->is_virtual():true,true,false).'> Produto virtual (sem entrega física)</label><label class="np-check"><input type="checkbox" name="sold_individually" value="1" '.checked($p?$p->is_sold_individually():true,true,false).'> Uma unidade por compra</label>';}
        echo '</div>'.Portal::textarea('Descrição','description',$p?$p->get_description():'',7).Portal::image_field('Imagem do produto','product_image',$p?absint($p->get_image_id()):0).Portal::button('Salvar produto').'</form></section>';
    }
    public static function export(array $d): void {
        if(!Portal::allowed()||!function_exists('wc_get_orders')){wp_die('Acesso restrito.','',['response'=>403]);}$f=PortalOrders::filters($d);if(is_wp_error($f)){Portal::flash($f->get_error_message(),true);Portal::redirect('sales');}nocache_headers();header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="vendas-'.$f['from'].'-'.$f['to'].'.csv"');$out=fopen('php://output','w');fwrite($out,"\xEF\xBB\xBF");fputcsv($out,['Pedido','Data','Situação','Produto','Quantidade','Valor do item','Moeda'],';','"','');$page=1;
        do{$batch=PortalOrders::listing($f,$page,200);foreach($batch['orders'] as $o){if($o->get_currency()!==$f['currency']){continue;}foreach(PortalOrders::visible_items($o,$f['course']) as $item){$row=[$o->get_order_number(),wp_date('d/m/Y H:i',$o->get_date_created()->getTimestamp()),self::statuses()[$o->get_status()]??$o->get_status(),$item->get_name(),$item->get_quantity(),number_format((float)$item->get_total()+(float)$item->get_total_tax(),2,',',''),$o->get_currency()];$row=array_map(static function($v){$v=(string)$v;return preg_match('/^[=+\-@\t\r]/',ltrim($v))?"'".$v:$v;},$row);fputcsv($out,$row,';','"','');}}$page++;}while($page<=$batch['pages']);fclose($out);exit;
    }
}
